using GravityShift.Levels;
using Yaeger.Graphics;

namespace GravityShift;

/// <summary>
/// Texture paths and tile layouts for the pixel art in <c>wwwroot/textures</c>, generated by
/// <c>tools/generate_art.py</c>. The paths are relative: URLs in the browser, files next to the
/// executable on desktop.
/// </summary>
public static class Art
{
    public const string Walls = "textures/walls.png";
    public const string Background = "textures/background.png";
    public const string Parcel = "textures/parcel.png";
    public const string Chute = "textures/chute.png";
    public const string Shredder = "textures/shredder.png";
    public const string Belts = "textures/belts.png";
    public const string Lock = "textures/lock.png";

    /// <summary>Every texture, for preloading.</summary>
    public static readonly IReadOnlyList<string> All =
    [
        Walls,
        Background,
        Parcel,
        Chute,
        Shredder,
        Belts,
        Lock,
    ];

    /// <summary>walls.png is a 4x4 sheet: tile index = the sides open to the room.</summary>
    public static Tileset WallTileset() => new(Walls, 4, 4, Enumerable.Range(0, 16));

    public static Tileset BackgroundTileset() => new(Background, 2);

    /// <summary>belts.png: 0 runs horizontally, 1 vertically. Belts are solid: you stand on them.</summary>
    public static Tileset BeltTileset() => new(Belts, 2, 1, [0, 1]);

    public const int OpenUp = 1;
    public const int OpenRight = 2;
    public const int OpenDown = 4;
    public const int OpenLeft = 8;

    /// <summary>
    /// The wall tile for a solid cell: which of its sides face open space (edges get a lit or
    /// shaded rim). Outside the map counts as wall, so the outer border stays plain.
    /// </summary>
    public static int WallTile(LevelData level, int column, int row)
    {
        bool Open(int c, int r) =>
            c >= 0 && r >= 0 && c < level.Width && r < level.Height && !level.IsSolid(c, r);

        return (Open(column, row - 1) ? OpenUp : 0)
            | (Open(column + 1, row) ? OpenRight : 0)
            | (Open(column, row + 1) ? OpenDown : 0)
            | (Open(column - 1, row) ? OpenLeft : 0);
    }
}
